css:
.dian-sim-container {
    padding: 24px;
    background: #f4f6fa;
    min-height: 100vh;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    color: #1f2a44;
}
.dian-sim-header {
    background: #0a2540;
    color: #f4f6fa;
    border-radius: 6px;
    margin-bottom: 20px;
    overflow: hidden;
    box-shadow: 0 6px 20px rgba(10,37,64,0.18);
}
.dian-sim-header-bar {
    height: 6px;
    background: linear-gradient(90deg, #fcd116 0%, #003893 50%, #ce1126 100%);
}
.dian-sim-header-content {
    padding: 24px 28px;
}
.dian-sim-eyebrow {
    text-transform: uppercase;
    letter-spacing: 0.14em;
    font-size: 0.7rem;
    color: #d4a017;
    margin-bottom: 8px;
}
.dian-sim-header h1 {
    font-size: 1.5rem;
    font-weight: 700;
    margin: 0 0 8px 0;
    letter-spacing: -0.01em;
}
.dian-sim-subtitle {
    font-size: 0.95rem;
    color: #a9b8d0;
    line-height: 1.5;
    max-width: 820px;
}
.dian-sim-period-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: white;
    border: 1px solid #d6dde8;
    border-left: 4px solid #d4a017;
    border-radius: 4px;
    padding: 12px 20px;
    margin-bottom: 20px;
}
.dian-sim-period-counter {
    font-size: 0.9rem;
    color: #4a5878;
    text-transform: uppercase;
    letter-spacing: 0.1em;
}
.dian-sim-period-counter span {
    margin-right: 4px;
}
.dian-sim-period-counter span:nth-child(2),
.dian-sim-period-counter span:nth-child(4) {
    color: #0a2540;
    font-weight: 700;
    font-size: 1rem;
}
.dian-sim-deadline {
    font-size: 0.85rem;
    color: #6b7280;
}
.dian-sim-deadline strong {
    color: #ce1126;
    margin-left: 6px;
    font-family: 'Segoe UI', sans-serif;
}
.dian-sim-status-cards {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(210px, 1fr));
    gap: 14px;
    margin-bottom: 22px;
}
.dian-sim-status-card {
    background: white;
    border: 1px solid #d6dde8;
    border-radius: 6px;
    padding: 18px 20px;
    border-top: 4px solid #1f2a44;
    transition: transform 0.2s ease, box-shadow 0.2s ease;
}
.dian-sim-status-card:hover {
    transform: translateY(-2px);
    box-shadow: 0 8px 20px rgba(10,37,64,0.08);
}
.dian-sim-card-cash { border-top-color: #1e6f5c; }
.dian-sim-card-sanction { border-top-color: #ce1126; }
.dian-sim-card-score { border-top-color: #003893; }
.dian-sim-card-time { border-top-color: #d4a017; }
.dian-sim-label {
    font-size: 0.7rem;
    text-transform: uppercase;
    letter-spacing: 0.12em;
    color: #6b7280;
    margin-bottom: 8px;
}
.dian-sim-value {
    font-size: 1.7rem;
    font-weight: 700;
    color: #0a2540;
    margin-bottom: 6px;
}
.dian-sim-card-sanction .dian-sim-value { color: #ce1126; }
.dian-sim-card-cash .dian-sim-value { color: #1e6f5c; }
.dian-sim-sub {
    font-size: 0.75rem;
    color: #6b7280;
    line-height: 1.4;
}
.dian-sim-briefing {
    background: white;
    border: 1px solid #d6dde8;
    border-left: 4px solid #003893;
    border-radius: 4px;
    padding: 20px 24px;
    margin-bottom: 20px;
}
.dian-sim-briefing-tag {
    font-size: 0.7rem;
    text-transform: uppercase;
    letter-spacing: 0.14em;
    color: #003893;
    font-weight: 600;
    margin-bottom: 8px;
}
.dian-sim-briefing h2 {
    font-size: 1.15rem;
    font-weight: 700;
    margin: 0 0 8px 0;
    color: #0a2540;
}
.dian-sim-briefing p {
    font-size: 0.92rem;
    line-height: 1.55;
    color: #1f2a44;
    margin: 0;
}
.dian-sim-controls {
    background: white;
    border: 1px solid #d6dde8;
    border-radius: 6px;
    padding: 22px 24px;
    margin-bottom: 20px;
}
.dian-sim-controls h3 {
    font-size: 1rem;
    font-weight: 700;
    color: #0a2540;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    margin: 0 0 16px 0;
    padding-bottom: 10px;
    border-bottom: 2px solid #d4a017;
}
.dian-sim-control-row {
    display: flex;
    flex-direction: column;
    gap: 6px;
    margin-bottom: 14px;
}
.dian-sim-control-row label {
    font-size: 0.85rem;
    font-weight: 600;
    color: #1f2a44;
}
.dian-sim-controls select,
.dian-sim-controls input {
    background: #ffffff;
    border: 1px solid #b8c2d4;
    color: #0a2540;
    border-radius: 4px;
    padding: 9px 12px;
    width: 100%;
    font-size: 0.92rem;
}
.dian-sim-controls select:focus,
.dian-sim-controls input:focus {
    outline: none;
    border-color: #003893;
    box-shadow: 0 0 0 3px rgba(0,56,147,0.15);
}
.dian-sim-controls select option {
    background: #ffffff;
    color: #0a2540;
}
.dian-sim-rationale {
    background: #f8f4e8;
    border: 1px solid #e8d999;
    border-radius: 4px;
    padding: 12px 16px;
    margin: 12px 0 16px 0;
}
.dian-sim-rationale-tag {
    font-size: 0.7rem;
    text-transform: uppercase;
    letter-spacing: 0.12em;
    color: #8a6d11;
    font-weight: 600;
    margin-bottom: 4px;
}
.dian-sim-rationale p {
    font-size: 0.85rem;
    line-height: 1.5;
    color: #5a4a14;
    margin: 0;
}
.dian-sim-actions {
    display: flex;
    gap: 10px;
    align-items: center;
    margin-top: 8px;
}
.dian-sim-actions .btn-primary {
    background: #0a2540;
    border-color: #0a2540;
    color: white;
    padding: 10px 22px;
    font-weight: 600;
    letter-spacing: 0.04em;
    border-radius: 4px;
}
.dian-sim-actions .btn-primary:hover {
    background: #14366a;
    border-color: #14366a;
}
.dian-sim-actions .btn-outline-secondary {
    color: #4a5878;
    border-color: #b8c2d4;
}
.dian-sim-result-panel {
    background: white;
    border: 1px solid #d6dde8;
    border-left: 4px solid #1e6f5c;
    border-radius: 4px;
    padding: 18px 22px;
    margin-bottom: 20px;
    font-size: 0.9rem;
    line-height: 1.6;
    color: #1f2a44;
}
.dian-sim-result-tag {
    font-size: 0.7rem;
    text-transform: uppercase;
    letter-spacing: 0.14em;
    color: #1e6f5c;
    font-weight: 600;
    margin-bottom: 8px;
}
.dian-sim-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 16px;
}
.dian-sim-history-block,
.dian-sim-chart-block {
    background: white;
    border: 1px solid #d6dde8;
    border-radius: 6px;
    padding: 18px 20px;
}
.dian-sim-history-block h3,
.dian-sim-chart-block h3 {
    font-size: 0.85rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    color: #4a5878;
    margin: 0 0 12px 0;
    padding-bottom: 8px;
    border-bottom: 1px solid #e5e9f0;
    font-weight: 700;
}
.dian-sim-history-block table {
    font-size: 0.82rem;
    color: #1f2a44;
}
.dian-sim-history-block th {
    background: #f4f6fa;
    color: #4a5878;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    font-size: 0.72rem;
    font-weight: 700;
    border-bottom: 2px solid #d6dde8;
    padding: 8px 6px;
}
.dian-sim-history-block td {
    padding: 8px 6px;
    border-bottom: 1px solid #e5e9f0;
}
.dian-sim-chart-block canvas {
    max-height: 280px;
}
@media (max-width: 768px) {
    .dian-sim-grid { grid-template-columns: 1fr; }
    .dian-sim-period-bar { flex-direction: column; align-items: flex-start; gap: 6px; }
    .dian-sim-header h1 { font-size: 1.2rem; }
    .dian-sim-value { font-size: 1.4rem; }
}

