(function() {
    'use strict';

    class DIANCustomsAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'DIAN Customs — Imports, Exports & Tariff Regime';
            this.version = '1.1.0';

            this.ROUNDS = [
                {
                    titleKey: 'round1_title',
                    briefKey: 'round1_brief',
                    rationaleKey: 'round1_rationale',
                    primaryLabelKey: 'r1_primary_label',
                    secondaryLabelKey: 'r1_secondary_label',
                    primaryKey: 'priority',
                    secondaryKey: 'approach',
                    primaryOptions: [
                        { value: 'valuation', i18n: 'r1_opt_valuation' },
                        { value: 'classification', i18n: 'r1_opt_classification' },
                        { value: 'export', i18n: 'r1_opt_export' }
                    ],
                    secondaryOptions: [
                        { value: 'defensive', i18n: 'r1_opt_defensive' },
                        { value: 'balanced', i18n: 'r1_opt_balanced' },
                        { value: 'aggressive', i18n: 'r1_opt_aggressive' }
                    ]
                },
                {
                    titleKey: 'round2_title',
                    briefKey: 'round2_brief',
                    rationaleKey: 'round2_rationale',
                    primaryLabelKey: 'r2_primary_label',
                    secondaryLabelKey: 'r2_secondary_label',
                    primaryKey: 'classification',
                    secondaryKey: 'documentation',
                    primaryOptions: [
                        { value: 'hold_8517', i18n: 'r2_opt_hold' },
                        { value: 'reclassify_8471', i18n: 'r2_opt_reclassify' },
                        { value: 'binding_ruling', i18n: 'r2_opt_binding' }
                    ],
                    secondaryOptions: [
                        { value: 'origin_repaper', i18n: 'r2_opt_repaper' },
                        { value: 'gri_memo', i18n: 'r2_opt_gri' },
                        { value: 'broker_letter', i18n: 'r2_opt_broker' }
                    ]
                },
                {
                    titleKey: 'round3_title',
                    briefKey: 'round3_brief',
                    rationaleKey: 'round3_rationale',
                    primaryLabelKey: 'r3_primary_label',
                    secondaryLabelKey: 'r3_secondary_label',
                    primaryKey: 'valuation',
                    secondaryKey: 'muisca',
                    primaryOptions: [
                        { value: 'accept_inspection', i18n: 'r3_opt_accept80' },
                        { value: 'accept_resolution', i18n: 'r3_opt_accept50' },
                        { value: 'full_appeal', i18n: 'r3_opt_appeal' }
                    ],
                    secondaryOptions: [
                        { value: 'correct_full', i18n: 'r3_opt_full' },
                        { value: 'correct_partial', i18n: 'r3_opt_partial' },
                        { value: 'no_correct', i18n: 'r3_opt_none' }
                    ]
                },
                {
                    titleKey: 'round4_title',
                    briefKey: 'round4_brief',
                    rationaleKey: 'round4_rationale',
                    primaryLabelKey: 'r4_primary_label',
                    secondaryLabelKey: 'r4_secondary_label',
                    primaryKey: 'export_fix',
                    secondaryKey: 'broker_governance',
                    primaryOptions: [
                        { value: 'corrected_eur1', i18n: 'r4_opt_amend' },
                        { value: 'supporting_decl', i18n: 'r4_opt_supporting' },
                        { value: 'reissue_eur1', i18n: 'r4_opt_reissue' }
                    ],
                    secondaryOptions: [
                        { value: 'audit_broker', i18n: 'r4_opt_audit' },
                        { value: 'renegotiate_sla', i18n: 'r4_opt_sla' },
                        { value: 'replace_broker', i18n: 'r4_opt_replace' }
                    ]
                }
            ];
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    cash: 2860,
                    sanctionExposure: 534,
                    complianceScore: 50,
                    timeUsed: 0,
                    priorityChoice: null,
                    approachChoice: null,
                    cashHistory: [],
                    sanctionHistory: [],
                    complianceHistory: [],
                    timeHistory: []
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    primary: 'valuation',
                    secondary: 'balanced'
                };
            }
            this._renderRound(state);
        }

        validateDecisions(decisions) {
            const primarySel = document.getElementById('primaryDecision');
            const secondarySel = document.getElementById('secondaryDecision');
            if (primarySel) decisions.primary = primarySel.value;
            if (secondarySel) decisions.secondary = secondarySel.value;

            if (!decisions.primary) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('decision_warning'), 'warning'
                );
                return false;
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let cashDelta = 0;
            let sanctionDelta = 0;
            let complianceDelta = 0;
            let timeDelta = 0;
            let outcomeKey = '';
            let outcomeNote = '';

            if (round === 1) {
                ds.priorityChoice = d.primary;
                ds.approachChoice = d.secondary;
                if (d.primary === 'valuation') {
                    complianceDelta = 8;
                    outcomeKey = 'r1_out_valuation';
                } else if (d.primary === 'classification') {
                    complianceDelta = 4;
                    outcomeKey = 'r1_out_classification';
                } else {
                    complianceDelta = -6;
                    sanctionDelta = 30;
                    outcomeKey = 'r1_out_export';
                }
                if (d.secondary === 'balanced') complianceDelta += 4;
                if (d.secondary === 'aggressive') { complianceDelta += 1; sanctionDelta += 10; }
                if (d.secondary === 'defensive') { complianceDelta += 2; timeDelta += 1; }
                timeDelta += 2;
            } else if (round === 2) {
                const aligned = ds.approachChoice === 'balanced';
                if (d.primary === 'hold_8517') {
                    if (aligned) {
                        cashDelta = 8;
                        sanctionDelta = -40;
                        complianceDelta = 5;
                        outcomeKey = 'r2_out_hold_ok';
                    } else {
                        cashDelta = -10;
                        sanctionDelta = 96;
                        complianceDelta = -8;
                        outcomeKey = 'r2_out_hold_fail';
                    }
                    timeDelta = 2;
                } else if (d.primary === 'reclassify_8471') {
                    cashDelta = -5;
                    sanctionDelta = 110;
                    complianceDelta = 8;
                    outcomeKey = 'r2_out_reclassify';
                    timeDelta = 4;
                } else {
                    cashDelta = -22;
                    sanctionDelta = -60;
                    complianceDelta = 18;
                    timeDelta = 12;
                    outcomeKey = 'r2_out_binding';
                }
                if (d.secondary === 'gri_memo') complianceDelta += 5;
                if (d.secondary === 'origin_repaper') { complianceDelta += 3; cashDelta -= 3; }
                if (d.secondary === 'broker_letter') complianceDelta -= 2;
            } else if (round === 3) {
                if (d.primary === 'accept_inspection') {
                    cashDelta = -249;
                    sanctionDelta = -284;
                    complianceDelta = 10;
                    outcomeKey = 'r3_out_accept80';
                    timeDelta = 1;
                } else if (d.primary === 'accept_resolution') {
                    cashDelta = -356;
                    sanctionDelta = -178;
                    complianceDelta = 4;
                    outcomeKey = 'r3_out_accept50';
                    timeDelta = 3;
                } else {
                    const winsAppeal = ds.complianceScore >= 65;
                    if (winsAppeal) {
                        cashDelta = -25;
                        sanctionDelta = -534;
                        complianceDelta = 16;
                        outcomeKey = 'r3_out_appeal_win';
                    } else {
                        cashDelta = -534;
                        sanctionDelta = -534;
                        complianceDelta = -10;
                        outcomeKey = 'r3_out_appeal_loss';
                    }
                    timeDelta = 5;
                }
                if (d.secondary === 'correct_full') complianceDelta += 8;
                else if (d.secondary === 'correct_partial') complianceDelta += 3;
                else { complianceDelta -= 6; sanctionDelta += 15; }
            } else if (round === 4) {
                if (d.primary === 'corrected_eur1') {
                    cashDelta = 45;
                    complianceDelta = 6;
                    outcomeKey = 'r4_out_amend';
                    timeDelta = 1;
                } else if (d.primary === 'supporting_decl') {
                    cashDelta = 42;
                    complianceDelta = 8;
                    outcomeKey = 'r4_out_supporting';
                    timeDelta = 2;
                } else {
                    cashDelta = 38;
                    complianceDelta = 4;
                    outcomeKey = 'r4_out_reissue';
                    timeDelta = 4;
                }
                if (d.secondary === 'audit_broker') complianceDelta += 12;
                else if (d.secondary === 'renegotiate_sla') { complianceDelta += 6; cashDelta -= 3; }
                else { complianceDelta += 8; cashDelta -= 20; }
            }

            ds.cash += cashDelta;
            ds.sanctionExposure = Math.max(0, ds.sanctionExposure + sanctionDelta);
            ds.complianceScore = Math.max(0, Math.min(100, ds.complianceScore + complianceDelta));
            ds.timeUsed += timeDelta;

            ds.cashHistory.push(ds.cash);
            ds.sanctionHistory.push(ds.sanctionExposure);
            ds.complianceHistory.push(ds.complianceScore);
            ds.timeHistory.push(ds.timeUsed);

            outcomeNote = window.mySimulation.t(outcomeKey);
            const resultPanel = document.getElementById('resultPanel');
            const resultText = document.getElementById('resultText');
            if (resultPanel && resultText) {
                resultPanel.style.display = 'block';
                resultText.innerHTML = outcomeNote
                    + '<br><br><strong>' + window.mySimulation.t('impact_label') + ':</strong> '
                    + window.mySimulation.t('cash_label') + ' '
                    + (cashDelta >= 0 ? '+' : '') + 'COP ' + cashDelta + 'M · '
                    + window.mySimulation.t('sanction_label') + ' '
                    + (sanctionDelta >= 0 ? '+' : '') + 'COP ' + sanctionDelta + 'M · '
                    + window.mySimulation.t('score_label') + ' '
                    + (complianceDelta >= 0 ? '+' : '') + complianceDelta + ' · '
                    + window.mySimulation.t('time_label') + ' +' + timeDelta + ' d';
            }

            const self = this;
            self._renderRound({ currentPeriod: state.currentPeriod + 1 });

            return {
                period: state.currentPeriod,
                primary: d.primary,
                secondary: d.secondary,
                cashDelta: cashDelta,
                sanctionDelta: sanctionDelta,
                complianceDelta: complianceDelta,
                timeDelta: timeDelta,
                cash: ds.cash,
                sanctionExposure: ds.sanctionExposure,
                complianceScore: ds.complianceScore,
                outcomeKey: outcomeKey
            };
        }

        _renderRound(state) {
            const period = state.currentPeriod || 1;
            const idx = Math.min(period - 1, this.ROUNDS.length - 1);
            const round = this.ROUNDS[idx];
            const t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : function(k) { return k; };

            const titleEl = document.getElementById('roundTitle');
            const briefEl = document.getElementById('briefingText');
            const rationaleEl = document.getElementById('rationaleText');
            const primaryLabelEl = document.getElementById('primaryLabel');
            const secondaryLabelEl = document.getElementById('secondaryLabel');
            const primarySel = document.getElementById('primaryDecision');
            const secondarySel = document.getElementById('secondaryDecision');

            if (titleEl) titleEl.textContent = t(round.titleKey);
            if (briefEl) briefEl.innerHTML = t(round.briefKey);
            if (rationaleEl) rationaleEl.innerHTML = t(round.rationaleKey);
            if (primaryLabelEl) primaryLabelEl.textContent = t(round.primaryLabelKey);
            if (secondaryLabelEl) secondaryLabelEl.textContent = t(round.secondaryLabelKey);

            if (primarySel) {
                primarySel.innerHTML = '';
                round.primaryOptions.forEach(function(opt) {
                    const o = document.createElement('option');
                    o.value = opt.value;
                    o.textContent = t(opt.i18n);
                    primarySel.appendChild(o);
                });
            }
            if (secondarySel) {
                secondarySel.innerHTML = '';
                round.secondaryOptions.forEach(function(opt) {
                    const o = document.createElement('option');
                    o.value = opt.value;
                    o.textContent = t(opt.i18n);
                    secondarySel.appendChild(o);
                });
            }
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('cashDisplay', 'domainState.cash',
                (v) => 'COP ' + Math.round(v).toLocaleString() + 'M');
            uiManager.bind('sanctionDisplay', 'domainState.sanctionExposure',
                (v) => 'COP ' + Math.round(v).toLocaleString() + 'M');
            uiManager.bind('scoreDisplay', 'domainState.complianceScore',
                (v) => Math.round(v));
            uiManager.bind('timeDisplay', 'domainState.timeUsed',
                (v) => Math.round(v) + ' d');
            const self = this;
            const undoBtn = document.getElementById('undoBtn');
            if (undoBtn) { undoBtn.addEventListener('click', function() { if (window.mySimulation && window.mySimulation.state) self._renderRound(window.mySimulation.state); }); }
        }

        getChartConfig() {
            return {
                exposureChart: {
                    type: 'line',
                    data: {
                        labels: [],
                        datasets: [
                            {
                                label: 'Sanction exposure (COP M)',
                                data: [],
                                borderColor: '#ce1126',
                                backgroundColor: 'rgba(206,17,38,0.1)',
                                borderWidth: 3,
                                fill: true,
                                tension: 0.2,
                                yAxisID: 'y'
                            },
                            {
                                label: 'Compliance score',
                                data: [],
                                borderColor: '#003893',
                                backgroundColor: 'rgba(0,56,147,0.08)',
                                borderWidth: 3,
                                fill: false,
                                tension: 0.2,
                                yAxisID: 'y1'
                            }
                        ]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            title: { display: false },
                            legend: { position: 'bottom', labels: { font: { size: 11 } } }
                        },
                        scales: {
                            y: {
                                type: 'linear',
                                position: 'left',
                                beginAtZero: true,
                                title: { display: true, text: 'COP M' }
                            },
                            y1: {
                                type: 'linear',
                                position: 'right',
                                beginAtZero: true,
                                max: 100,
                                title: { display: true, text: 'Score (0–100)' },
                                grid: { drawOnChartArea: false }
                            }
                        }
                    }
                }
            };
        }

        getChartData(state) {
            const labels = state.domainState.sanctionHistory.map((_, i) => 'R' + (i + 1));
            return {
                exposureChart: {
                    labels: labels,
                    datasets: [
                        { data: state.domainState.sanctionHistory },
                        { data: state.domainState.complianceHistory }
                    ]
                }
            };
        }

        getHint(state, results) {
            const ds = state.domainState;
            if (results && results.outcomeKey === 'r2_out_hold_fail') {
                return window.mySimulation.t('hint_classification_fail');
            }
            if (results && results.outcomeKey === 'r3_out_appeal_loss') {
                return window.mySimulation.t('hint_appeal_loss');
            }
            if (ds.complianceScore < 40) {
                return window.mySimulation.t('hint_low_compliance');
            }
            if (ds.sanctionExposure > 400) {
