        getPerformanceSummary(history) {
            if (!history.length) return {};
            const last = history[history.length - 1];
            const finalSanction = last.results && last.results.sanctionExposure !== undefined
                ? last.results.sanctionExposure : 534;
            const finalScore = last.results && last.results.complianceScore !== undefined
                ? last.results.complianceScore : 50;
            const finalCash = last.results && last.results.cash !== undefined
                ? last.results.cash : 2860;

            const sanctionReduction = ((534 - finalSanction) / 534) * 100;
            let performance = 'Beginner';
            const insights = [];

            if (sanctionReduction > 70 && finalScore > 70) {
                performance = 'Excellent';
                insights.push(window.mySimulation.t('insight_excellent'));
            } else if (sanctionReduction > 40 && finalScore > 55) {
                performance = 'Good';
                insights.push(window.mySimulation.t('insight_good'));
            } else if (sanctionReduction > 0) {
                performance = 'Adequate';
                insights.push(window.mySimulation.t('insight_adequate'));
            } else {
                performance = 'Poor';
                insights.push(window.mySimulation.t('insight_poor'));
            }

            if (finalScore < 50) insights.push(window.mySimulation.t('insight_governance'));
            if (finalCash < 2400) insights.push(window.mySimulation.t('insight_cash'));

            return {
                finalSanction: finalSanction,
                finalScore: finalScore,
                finalCash: finalCash,
                sanctionReduction: Math.round(sanctionReduction),
                performance: performance,
                insights: insights
            };
        }

